nextflow_process {

    name "Test Process SPADES"
    script "../main.nf"
    process "SPADES"
    config "./nextflow.config"
    tag "modules"
    tag "modules_nfcore"
    tag "spades"

    test("sarscov2 - se ") {

        when {
            process {
                """
                input[0] = [ [ id:'test', single_end:true ],
                                [ file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_2.fastq.gz", checkIfExists: true) ],
                                [],
                                []
                            ]
                input[1] = []
                input[2] = []
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out.scaffolds,
                    process.out.contigs,
                    process.out.transcripts,
                    process.out.gene_clusters,
                    process.out.gfa,
                    process.out.versions_spades
                    ).match() },
                { assert path(process.out.log[0][1]).readLines().any { it.contains("SPAdes pipeline finished") } }
            )
        }
    }

    test("sarscov2 - pe ") {

        when {
            process {
                """
                input[0] = [ [ id:'test', single_end:false ], // meta map
                            [ file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_1.fastq.gz", checkIfExists: true),
                                file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_2.fastq.gz", checkIfExists: true) ],
                            [],
                            []
                        ]
                input [1] = []
                input [2] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out.scaffolds,
                    process.out.contigs,
                    process.out.transcripts,
                    process.out.gene_clusters,
                    process.out.gfa,
                    process.out.versions_spades
                    ).match() },
                { assert path(process.out.log[0][1]).readLines().any { it.contains("SPAdes pipeline finished") } },
                { assert file(process.out.warnings[0][1]).find{ file(it).name == "warnings.log"} }
            )
        }

    }
